// ---------------------------------------------------------------------------
//  UTF-8 for the snapshot
// ---------------------------------------------------------------------------
static bool IsValidUtf8(const std::string& s)
{
    size_t i = 0;
    while (i < s.size())
    {
        const unsigned char c = (unsigned char)s[i];
        int n = 0;
        if (c < 0x80) n = 0;
        else if ((c & 0xE0) == 0xC0 && c >= 0xC2) n = 1;
        else if ((c & 0xF0) == 0xE0) n = 2;
        else if ((c & 0xF8) == 0xF0 && c <= 0xF4) n = 3;
        else return false;
        for (int k = 1; k <= n; ++k)
            if (i + k >= s.size() || ((unsigned char)s[i + k] & 0xC0) != 0x80) return false;
        i += n + 1;
    }
    return true;
}

std::string ToUtf8(const std::string& s)
{
    if (IsValidUtf8(s)) return s;
    const int wn = ::MultiByteToWideChar(950, 0, s.data(), (int)s.size(), NULL, 0);
    if (wn <= 0) return std::string();
    std::vector<wchar_t> w((size_t)wn);
    ::MultiByteToWideChar(950, 0, s.data(), (int)s.size(), &w[0], wn);
    const int un = ::WideCharToMultiByte(CP_UTF8, 0, &w[0], wn, NULL, 0, NULL, NULL);
    if (un <= 0) return std::string();
    std::string out((size_t)un, '\0');
    ::WideCharToMultiByte(CP_UTF8, 0, &w[0], wn, &out[0], un, NULL, NULL);
    return out;
}

// ===========================================================================
//  UTF-8 validation (RFC 3629): used for text messages and close reasons
// ===========================================================================
bool WsDecoder::IsValidUtf8(const std::string& s) {
    std::size_t i = 0, n = s.size();
    while (i < n) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        std::size_t extra;
        uint32_t cp;
        if (c < 0x80) { ++i; continue; }
        else if ((c & 0xE0) == 0xC0) { extra = 1; cp = c & 0x1F; }
        else if ((c & 0xF0) == 0xE0) { extra = 2; cp = c & 0x0F; }
        else if ((c & 0xF8) == 0xF0) { extra = 3; cp = c & 0x07; }
        else return false;                       // 0x80-0xBF stray, or 0xF8+
        // Continuation bytes live at i+1 .. i+extra, so they all exist only if
        // i + extra <= n - 1. A sequence cut short by the end of the string is
        // invalid (this is a whole-message check, not a streaming one).
        if (i + extra >= n) return false;
        for (std::size_t k = 1; k <= extra; ++k) {
            unsigned char cc = static_cast<unsigned char>(s[i + k]);
            if ((cc & 0xC0) != 0x80) return false;
            cp = (cp << 6) | (cc & 0x3F);
        }
        // Reject overlong encodings, UTF-16 surrogates, and > U+10FFFF.
        if (extra == 1 && cp < 0x80) return false;
        if (extra == 2 && cp < 0x800) return false;
        if (extra == 3 && cp < 0x10000) return false;
        if (cp >= 0xD800 && cp <= 0xDFFF) return false;
        if (cp > 0x10FFFF) return false;
        i += extra + 1;
    }
    return true;
}

// ---- text: file-system names are ANSI (cp950); JSON is UTF-8 ----
std::string U8(const AnsiString& a)
{
    const std::string s = a.c_str();
    if (webbridge::IsValidUtf8(s)) return s;
    const int wn = MultiByteToWideChar(CP_ACP, 0, s.c_str(), (int)s.size(), NULL, 0);
    if (wn <= 0) return webbridge::SanitizeToUtf8(s);
    std::wstring w((size_t)wn, L'\0');
    MultiByteToWideChar(CP_ACP, 0, s.c_str(), (int)s.size(), &w[0], wn);
    const int un = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), wn, NULL, 0, NULL, NULL);
    std::string u((size_t)(un > 0 ? un : 0), '\0');
    if (un > 0) WideCharToMultiByte(CP_UTF8, 0, w.c_str(), wn, &u[0], un, NULL, NULL);
    return u;
}

